-- J2b: Pfam architecture per protein, chunked by protein_id prefix (pfam.parquet is ordered by protein_id).
-- @output A5/tmhmm_predhel_check.parquet
COPY (SELECT count(*) AS n_rows, count(*) FILTER (WHERE PredHel = 0) AS n_predhel0, count(*) FILTER (WHERE PredHel >= 2) AS n_predhel2, min(PredHel) AS min_predhel FROM '{T}/tmhmm.parquet') TO '{OUT}' (FORMAT PARQUET, COMPRESSION ZSTD);
-- @output A3/arch_chunks/arch_0.parquet
COPY (SELECT protein_id, count(*) AS n_domains, count(DISTINCT split_part(pfam_acc,'.',1)) AS n_distinct_domains, string_agg(split_part(pfam_acc,'.',1), ';' ORDER BY env_from, env_to) AS pfam_arch, min(env_from) AS first_env_from, max(env_to) AS last_env_to FROM '{T}/pfam.parquet' WHERE domain_i_evalue <= 1e-5 AND protein_id >= 'F0' AND protein_id < 'F1' GROUP BY 1) TO '{OUT}' (FORMAT PARQUET, COMPRESSION ZSTD);
-- @output A3/arch_chunks/arch_1.parquet
COPY (SELECT protein_id, count(*) AS n_domains, count(DISTINCT split_part(pfam_acc,'.',1)) AS n_distinct_domains, string_agg(split_part(pfam_acc,'.',1), ';' ORDER BY env_from, env_to) AS pfam_arch, min(env_from) AS first_env_from, max(env_to) AS last_env_to FROM '{T}/pfam.parquet' WHERE domain_i_evalue <= 1e-5 AND protein_id >= 'F1' AND protein_id < 'F2' GROUP BY 1) TO '{OUT}' (FORMAT PARQUET, COMPRESSION ZSTD);
