-- @output A3/protein_pfam_arch.parquet
COPY (SELECT * FROM read_parquet('{A}/A3/arch_chunks/arch_*.parquet') ORDER BY protein_id) TO '{OUT}' (FORMAT PARQUET, COMPRESSION ZSTD);
